public class TFMDataSourceParameterAttribute extends SysAttribute implements SysExtensionIAttribute
{
    str						GroupString;
    LabelString             LabelString;
    anytype                 defaultValue;
    HelpTxt                 helpText;

}

Method.Source:
void new(anytype _defaultValue, LabelString _labelString = '', str _groupString = '', HelpTxt _helpText = '')
{
    super();

    labelString = _labelString;
    defaultValue = _defaultValue;
    GroupString = _groupString;
    helpText = _helpText;
}

public anytype parmDefaultValue(anytype _defaultValue = defaultValue)
{
    defaultValue = _defaultValue;
    return defaultValue;
}

public str parmGroupString(str _GroupString = GroupString)
{
    GroupString = _GroupString;

    return GroupString ? GroupString : "@SYS315099";
}

public LabelString parmLabelString(LabelString _labelString = LabelString)
{
    LabelString = _labelString;

    return LabelString;
}

public LabelString parmHelpText(LabelString _helpText = helpText)
{
    helpText = _helpText;

    return helpText;
}

public str parmCacheKey()
{
    return classStr(TFMDataSourceParameterAttribute)+';'+';' + GroupString +';' + LabelString;
}
